"""Core execution backends for dataforge."""


class Backend:
    """Base class for execution backends."""

    name = "base"

    def execute(self, stage):
        raise NotImplementedError("Backends must implement execute()")

    def __repr__(self):
        return "<{} name={!r}>".format(type(self).__name__, self.name)


class NativeBackend(Backend):
    """Backend that executes pipeline stages in-process.

    Parameters
    ----------
    compiled:
        When True, stages are executed via the (simulated) compiled fast path.
    """

    name = "native"

    def __init__(self, compiled=False):
        self.compiled = bool(compiled)

    def execute(self, stage):
        mode = "compiled" if self.compiled else "interpreted"
        return "{}:{}:{}".format(self.name, mode, stage)

    def __repr__(self):
        return "<NativeBackend compiled={}>".format(self.compiled)

"""Pure-Python fallback for the dataforge native ("compiled") backend.

This module stands in for the optional C extension ``dataforge._native``.
It exposes the same :class:`_Backend` interface expected by
:mod:`dataforge.core` so the compiled fast path works without a build step.
"""

COMPILED = True


class _Backend:
    """Compiled-path backend implementation (pure-Python fallback)."""

    name = "native-compiled"

    def __init__(self, *args, **kwargs):
        self.args = args
        self.kwargs = kwargs

    def execute(self, stage):
        return "native:compiled:{}".format(stage)

    def run(self, stage):
        return self.execute(stage)

    def __repr__(self):
        return "<_Backend name={!r}>".format(self.name)

