/* dataforge._native: compiled fast-path backend. */
#define PY_SSIZE_T_CLEAN
#include <Python.h>

static PyObject *backend_execute(PyObject *self, PyObject *args) {
    const char *stage;
    if (!PyArg_ParseTuple(args, "s", &stage)) {
        return NULL;
    }
    return PyUnicode_FromFormat("native:compiled:%s", stage);
}

static PyMethodDef BackendMethods[] = {
    {"execute", backend_execute, METH_VARARGS, "Execute a pipeline stage."},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef nativemodule = {
    PyModuleDef_HEAD_INIT, "_native", "dataforge native backend", -1, BackendMethods
};

PyMODINIT_FUNC PyInit__native(void) {
    PyObject *m = PyModule_Create(&nativemodule);
    if (m == NULL) return NULL;
    /* _Backend type registered lazily by the Python wrapper. */
    return m;
}

